package com.stacklab.controller;
import com.stacklab.dto.ApiDtos.*;import com.stacklab.repository.ActivityRepository;import com.stacklab.service.ProjectService;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import org.springdoc.core.annotations.ParameterObject;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/projects") @SecurityRequirement(name="bearerAuth") public class ProjectController{private final ProjectService projects;private final ActivityRepository activities;public ProjectController(ProjectService p,ActivityRepository a){projects=p;activities=a;}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") public org.springframework.http.ResponseEntity<ProjectView> create(@Valid @RequestBody ProjectInput r){return org.springframework.http.ResponseEntity.status(201).body(projects.create(r));}@GetMapping public Page<ProjectView> list(@RequestParam(required=false)String q,@RequestParam(required=false)Boolean archived,@ParameterObject @PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return projects.list(q,archived,p);}@GetMapping("/{id}")public ProjectView get(@PathVariable Long id){return projects.get(id);}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','MANAGER')")public ProjectView update(@PathVariable Long id,@Valid @RequestBody ProjectInput r){return projects.update(id,r);}@GetMapping("/{id}/activity")public java.util.List<ActivityView> history(@PathVariable Long id){projects.get(id);return activities.findByProjectIdOrderByOccurredAtDesc(id).stream().map(ActivityView::of).toList();}}
